def plan(library, question, law_material):
    frame = query_frame(question)
    if digest(law_material) != library['law_digest']:
        def bodies(material):
            result = {}
            for body in material.values():
                heading = re.match(r'^\s*§\s*(\d+)\.',body)
                if heading:
                    section = heading[1]
                    if section in result and result[section] != body:
                        raise ValueError('Conflicting supplied versions of the same source')
                    result[section] = body
            return result
        learned, current = bodies(library['law_material']), bodies(law_material)
        if any(learned[s] != current[s] for s in set(learned) & set(current)):
            raise ValueError('Current law differs from the acquired source version')
        section = frame['clause'].split('(')[0] if frame else None
        if section not in learned or section not in current:
            raise ValueError('Reuse requires the queried source version in both contexts')
    matches = [u for u in library['units'].values() if frame and
               (u['clause'], u['kind']) == (frame['clause'], frame['kind'])]
    if len(matches) != 1:
        return {'supported': False, 'frame': frame, 'unit': None, 'fields': {}}
    unit = matches[0]
    scope = literal_query_arguments(question)
    bound = {a['name']: scope['values'][a['selector']] for a in unit['arguments']
             if a['selector'] in scope['values']}
    fields, blocked = {}, []
    for f in unit['fields']:
        ports = set(re.findall(r'\{([A-Za-z_][A-Za-z0-9_]*)\}',f['question']))
        if not ports <= set(bound):
            blocked.append(f['name'])
            continue
        prompt = re.sub(r'\{([A-Za-z_][A-Za-z0-9_]*)\}',lambda m:str(bound[m[1]]),f['question'])
        fields[f['name']] = {'type': f['type'], 'question': prompt}
    return {'supported': True, 'frame': frame, 'unit': unit['id'], 'fields': fields,
            'query_arguments': bound, 'query_argument_evidence': scope['evidence'],
            'unresolved_query_arguments': [a['name'] for a in unit['arguments'] if a['name'] not in bound],
            'unresolved_factual_questions': blocked}


def evaluate(library, planned, known_case_values):
    if not planned['supported']:
        return {'answer': 'unknown', 'value': None, 'used_units': [],
                'open_dependencies': ['No acquired callable source head for this query.']}
    unit = library['units'][planned['unit']]
    if not set(known_case_values) <= {f['name'] for f in unit['fields']}:
        raise ValueError('Case binding outside the acquired unit interface')
    declarations = {f['name']: f for f in unit['fields']}
    for name, value in known_case_values.items():
        jsonschema.validate(value, {'type': declarations[name]['type']})
    arguments = {a['name']: a for a in unit['arguments']}
    if not set(planned['query_arguments']) <= set(arguments):
        raise ValueError('Query binding outside the acquired argument contract')
    for name,value in planned['query_arguments'].items():
        jsonschema.validate(value,{'type':arguments[name]['type']})
    bindings = {**planned['query_arguments'], **known_case_values}
    # Neither native question/claim nor labels/source IDs enter legal execution.
    result = execute(entry_program(library, unit['id']), {'facts': bindings})
    if set(result) != {'value', 'used_units', 'open_dependencies'}:
        raise ValueError('Callable rule must return its property and proof obligations')
    if not isinstance(result['used_units'], list) or not set(result['used_units']) <= set(library['units']):
        raise ValueError('Rule execution cites an unacquired unit')
    if not isinstance(result['open_dependencies'], list) or any(not isinstance(x, str) for x in result['open_dependencies']):
        raise ValueError('Explicit unresolved proof obligations required')
    value = result['value']
    if value is None:
        return {'answer': 'unknown', **result}
    if result['open_dependencies']:
        raise ValueError('A claimed definite property still has blocking proof obligations')
    if unit['kind'] == 'predicate':
        if type(value) is not bool:
            raise ValueError('Predicate result must be boolean or unresolved')
        truth = value
    else:
        if type(value) not in (int, float) or not math.isfinite(value):
            raise ValueError('Quantity result must be finite numeric or unresolved')
        truth = value == planned['frame']['claim']
    if planned['frame']['negated']:
        truth = not truth
    return {'answer': 'Entailment' if truth else 'Contradiction', **result}
", "later_case_text_questions_labels": "not supplied", "law_material": {"referenced_public_sections.152": "§152. Dependent defined

(a) In general

For purposes of this subtitle, the term "dependent" means-

    (1) a qualifying child, or

    (2) a qualifying relative.

(b) Exceptions

For purposes of this section-

    (1) Dependents ineligible

    If an individual is a dependent of a taxpayer for any taxable year of such taxpayer beginning in a calendar year, such individual shall be treated as having no dependents for any taxable year of such individual beginning in such calendar year.

    (2) Married dependents

    An individual shall not be treated as a dependent of a taxpayer under subsection (a) if such individual has made a joint return with the individual's spouse for the taxable year beginning in the calendar year in which the taxable year of the taxpayer begins.

(c) Qualifying child

For purposes of this section-

    (1) In general

    The term "qualifying child" means, with respect to any taxpayer for any taxable year, an individual-

        (A) who bears a relationship to the taxpayer described in paragraph (2),

        (B) who has the same principal place of abode as the taxpayer for more than one-half of such taxable year,

        (C) who meets the age requirements of paragraph (3), and

        (E) who has not filed a joint return (other than only for a claim of refund) with the individual's spouse for the taxable year beginning in the calendar year in which the taxable year of the taxpayer begins.

    (2) Relationship

    For purposes of paragraph (1)(A), an individual bears a relationship to the taxpayer described in this paragraph if such individual is-

        (A) a child of the taxpayer or a descendant of such a child, or

        (B) a brother, sister, stepbrother, or stepsister of the taxpayer or a descendant of any such relative.

    (3) Age requirements

    For purposes of paragraph (1)(C), an individual meets the requirements of this paragraph if such individual is younger than the taxpayer claiming such individual as a qualifying child and is less than 25 years old at the end of the taxable year.

(d) Qualifying relative

For purposes of this section-

    (1) In general

    The term "qualifying relative" means, with respect to any taxpayer for any taxable year, an individual-

        (A) who bears a relationship to the taxpayer described in paragraph (2),

        (B) who has no income for the calendar year in which such taxable year begins, and

        (D) who is not a qualifying child of such taxpayer or of any other taxpayer for any taxable year beginning in the calendar year in which such taxable year begins.

    (2) Relationship

    For purposes of paragraph (1)(A), an individual bears a relationship to the taxpayer described in this paragraph if the individual is any of the following with respect to the taxpayer:

        (A) A child or a descendant of a child.

        (B) A brother, sister, stepbrother, or stepsister.

        (C) The father or mother, or an ancestor of either.

        (D) A stepfather or stepmother.

        (E) A son or daughter of a brother or sister of the taxpayer.

        (F) A brother or sister of the father or mother of the taxpayer.

        (G) A son-in-law, daughter-in-law, father-in-law, mother-in-law, brother-in-law, or sister-in-law.

        (H) An individual (other than an individual who at any time during the taxable year was the spouse, determined without regard to section 7703, of the taxpayer) who, for the taxable year of the taxpayer, has the same principal place of abode as the taxpayer and is a member of the taxpayer's household.
